-- Same fix as V222, applied to tenant_id=1's OWN forked workflow_definition
-- rows (a real tenant that had already diverged from the product-default
-- (tenant_id=-1) definitions V222 touched — WorkflowDefinitionRepository
-- prefers a tenant's own fork over -1 per findLatestPublished's
-- "ORDER BY tenantId DESC, version DESC", so V222 alone never reaches this
-- tenant's running instances at all).
--
-- M10.TankerInbound: tenant 1 had already forked all the way to version 9,
-- with its own customizations preserved here as-is (an unused/orphaned
-- LOADING_IN_PROGRESS state with no transition referencing it, and
-- QC_APPROVED assigned to WeighmentOfficer instead of the product-default's
-- Dispatch) — only the GATE_PASS_CREATED re-rooting changes.
-- M10.PackUnload / M10.ReturnStockIn: tenant 1's version 1 was identical in
-- shape to the product-default version 1 V222 already handled, so the same
-- delta applies unchanged.

-- ---------------------------------------------------------------------------
-- 1. Archive tenant 1's old versions.
UPDATE workflow_definition SET status = 'ARCHIVED'
 WHERE tenant_id = 1 AND status = 'PUBLISHED' AND code = 'M10.TankerInbound' AND version = 9;
UPDATE workflow_definition SET status = 'ARCHIVED'
 WHERE tenant_id = 1 AND status = 'PUBLISHED' AND code = 'M10.PackUnload' AND version = 1;
UPDATE workflow_definition SET status = 'ARCHIVED'
 WHERE tenant_id = 1 AND status = 'PUBLISHED' AND code = 'M10.ReturnStockIn' AND version = 1;

-- 2. New next-version definitions for tenant 1.
INSERT INTO workflow_definition (tenant_id, code, version, status, body_json)
SELECT 1, 'M10.TankerInbound', 10, 'PUBLISHED', '{"code":"M10.TankerInbound","version":10,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"DISPATCH_QUEUED","assignedRole":"QC"},{"code":"QC_APPROVED","assignedRole":"WeighmentOfficer"},{"code":"QC_REJECTED","terminal":true},{"code":"SUPERVISOR_ALLOCATED","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_1","assignedRole":"UnloadingSupervisor"},{"code":"UNLOADING_DONE","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_2","assignedRole":"Dispatch"},{"code":"QTY_RECONCILED","assignedRole":"WeighmentOfficer"},{"code":"QTY_PENDING_MANAGER","assignedRole":"Manager"},{"code":"WEIGHMENT_3","assignedRole":"FrontGate"},{"code":"WEIGHT_DIFF_PENDING_MANAGER","assignedRole":"Manager"},{"code":"CLOSED","terminal":true},{"code":"REJECTED_BY_MANAGER","terminal":true},{"code":"LOADING_IN_PROGRESS","assignedRole":"UnloadingSupervisor"}],"transitions":[{"from":"DRAFT","to":"DISPATCH_QUEUED","trigger":"page.submitted","pageCode":"aria:dispatch-vehicle-details"},{"from":"DISPATCH_QUEUED","to":"QC_APPROVED","trigger":"page.submitted","pageCode":"aria:qc-approval","guard":"#submitted[\'status\'] == \'APPROVED\'"},{"from":"DISPATCH_QUEUED","to":"QC_REJECTED","trigger":"page.submitted","pageCode":"aria:qc-approval","guard":"#submitted[\'status\'] == \'REJECTED\'"},{"from":"QC_APPROVED","to":"WEIGHMENT_1","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_1","to":"UNLOADING_DONE","trigger":"page.submitted","pageCode":"aria:supervisor-unloading"},{"from":"UNLOADING_DONE","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_2","to":"QTY_RECONCILED","trigger":"page.submitted","pageCode":"aria:reconciliation","guard":"#submitted[\'withinTolerance\'] == \'YES\'"},{"from":"WEIGHMENT_2","to":"QTY_PENDING_MANAGER","trigger":"page.submitted","pageCode":"aria:reconciliation","guard":"#submitted[\'withinTolerance\'] == \'NO\'"},{"from":"QTY_PENDING_MANAGER","to":"QTY_RECONCILED","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[\'status\'] == \'APPROVED\'"},{"from":"QTY_PENDING_MANAGER","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[\'status\'] == \'REJECTED\'"},{"from":"QTY_RECONCILED","to":"WEIGHMENT_3","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_3","to":"CLOSED","trigger":"page.submitted","pageCode":"aria:gate-pass-closure","guard":"#submitted[\'withinTolerance\'] == \'YES\'"},{"from":"WEIGHMENT_3","to":"WEIGHT_DIFF_PENDING_MANAGER","trigger":"page.submitted","pageCode":"aria:gate-pass-closure","guard":"#submitted[\'withinTolerance\'] == \'NO\'"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"CLOSED","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[\'status\'] == \'APPROVED\'"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[\'status\'] == \'REJECTED\'"}]}'
WHERE NOT EXISTS (SELECT 1 FROM workflow_definition WHERE tenant_id = 1 AND code = 'M10.TankerInbound' AND version = 10);

